package com.bank.codeindex;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class FirstCharDemo {
    private static final Logger log = Logger.getLogger("CodeIndex");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> codes = List.of("Savings", "Salary", "Current", "Credit", "", "Trading");
        CodeIndexService service = new CodeIndexService();

        Map<Character, List<String>> index = service.byFirstChar(codes);
        index.forEach((c, list) -> log.info(() -> c + " → " + list));
    }
}

// ─── Would be in service/CodeIndexService.java ───
class CodeIndexService {
    Map<Character, List<String>> byFirstChar(List<String> codes) {
        return codes.stream()
            .filter(s -> s != null && !s.isEmpty())           // guard empty/null
            .collect(groupingBy(
                s -> Character.toUpperCase(s.charAt(0)),        // first char, case-normalised
                TreeMap::new,                                   // alphabetical keys
                toList()));
    }
}
